export default JSON.parse("{\"workId\":\"liezi\",\"chapter\":{\"id\":\"liezi_ch-4\",\"workId\":\"liezi\",\"order\":4,\"title\":\"仲尼\",\"difficulty\":2,\"estimatedMinutes\":32,\"passageIds\":[\"liezi_ch-4_p-1\",\"liezi_ch-4_p-2\",\"liezi_ch-4_p-3\",\"liezi_ch-4_p-4\",\"liezi_ch-4_p-5\",\"liezi_ch-4_p-6\",\"liezi_ch-4_p-7\",\"liezi_ch-4_p-8\",\"liezi_ch-4_p-9\",\"liezi_ch-4_p-10\",\"liezi_ch-4_p-11\",\"liezi_ch-4_p-12\",\"liezi_ch-4_p-13\",\"liezi_ch-4_p-14\",\"liezi_ch-4_p-15\",\"liezi_ch-4_p-16\"],\"tags\":[]},\"passages\":[{\"id\":\"liezi_ch-4_p-1\",\"chapterId\":\"liezi_ch-4\",\"order\":1,\"canonicalText\":\"仲尼閑居，子貢入侍，而有憂色。子貢不敢問，出告顏回。顏回援琴而歌。孔子聞之，果召回入，問曰：「若奚獨樂？」回曰：「夫子奚獨憂？」孔子曰：「先言爾志。」曰：「吾昔聞之夫子曰：『樂天知命故不憂。』回所以樂也。」孔子愀然有間，曰：「有是言哉？汝以夫子之言為盡然邪？此吾昔日之小知也。曏者吾所言樂天知命，特未見其大者耳。今吾憂者，憂天下之不治，億兆之不寧，道之不行，德之不章。吾何能不憂哉？樂天知命者，小人之自全也；憂世憫人者，聖人之宏願也。」\",\"sentenceIds\":[\"liezi_ch-4_p-1_s-1\",\"liezi_ch-4_p-1_s-2\",\"liezi_ch-4_p-1_s-3\",\"liezi_ch-4_p-1_s-4\",\"liezi_ch-4_p-1_s-5\",\"liezi_ch-4_p-1_s-6\",\"liezi_ch-4_p-1_s-7\",\"liezi_ch-4_p-1_s-8\",\"liezi_ch-4_p-1_s-9\",\"liezi_ch-4_p-1_s-10\",\"liezi_ch-4_p-1_s-11\",\"liezi_ch-4_p-1_s-12\",\"liezi_ch-4_p-1_s-13\",\"liezi_ch-4_p-1_s-14\",\"liezi_ch-4_p-1_s-15\",\"liezi_ch-4_p-1_s-16\",\"liezi_ch-4_p-1_s-17\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"孔子平日獨自閒居在室內，子貢進來侍奉，看見孔子臉上帶有深深的憂愁之色。子貢不敢直接開口詢問，退出來告訴了顏回。顏回於是手抱古琴在門外從容彈奏放聲高歌。孔子在室內聽見琴歌之聲，果然召見顏回進屋，問道：你為什麼獨自一人如此快樂呢？顏回反問道：先生又為什麼獨自一人如此憂愁呢？孔子說：你先說說你的想法志向。顏回說：我過去聽先生親口教導說：順應樂享天道、通曉知曉天命，所以內心永遠不會有憂愁焦慮（樂天知命故不憂）。這就是我顏回之所以能夠快樂的原因啊。孔子神色嚴肅沉思了良久，說道：我過去真的說過這句話嗎？你難道以為我當初說的話就完全是終極真理了嗎？那隻不過是我過去在認知尚淺時的小聰明小智慧罷了！過去我所說的樂天知命，只不過是還沒有看見更加宏大崇高的境界罷了！如今我內心所深深憂慮的，是憂慮全天下的政治尚未實現清明治平，億萬無辜黎民百姓尚未獲得安寧幸福，真理大道尚未在人間普遍推行，崇高道德尚未在社會光輝彰顯。面對這一切，我又怎麼可能做到不憂愁呢？獨自一人樂天知命自得其樂，只不過是普通自私之輩用以保全自身的狹隘手段；而為天下世道憂心忡忡、為天下苦難蒼生慈悲憫恤，這才是至高聖人胸懷天下的宏偉大願啊！\",\"analysis\":\"【篇旨與仲尼篇開篇樂天知命與憂世憫人兩重境界】〈仲尼〉開篇——通過孔子與顏回問答，超越道家個人逍遙保全之「樂天知命」，確立儒道合流下聖人「憂天下不治、憂世憫人」的天下擔當大願。\\\\n【詞義訓詁】「樂天知命故不憂」：語出《周易・繫辭上》；「小知」：局限於個體解脫之淺見；「憂世憫人」：以天下蒼生福祉為己任的博大慈悲。\\\\n【境界昇華】將個人身心調適（樂天知命）提升至社會責任與人類命運共同體（憂世憫人）的崇高維度。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-4_p-2\",\"chapterId\":\"liezi_ch-4\",\"order\":2,\"canonicalText\":\"亢倉子居陳，人告亢倉子於陳侯，曰：「亢倉子得老聃之道，能以耳視而目聽。」陳侯異之，使使厚幣聘之。亢倉子至，陳侯問其術。亢倉子曰：「傳者妄也。臣能使耳目相通，不能使耳目代用。」陳侯曰：「若此者，何道邪？」亢倉子曰：「臣之體神凝形釋，骨肉都融。臣不知形之所居，足之所履，心之所念，言之所藏。眼如耳，耳如鼻，鼻如口，口無不同。天下之物，至無不通，至無不察。此臣之所謂耳目相通也。」\",\"sentenceIds\":[\"liezi_ch-4_p-2_s-1\",\"liezi_ch-4_p-2_s-2\",\"liezi_ch-4_p-2_s-3\",\"liezi_ch-4_p-2_s-4\",\"liezi_ch-4_p-2_s-5\",\"liezi_ch-4_p-2_s-6\",\"liezi_ch-4_p-2_s-7\",\"liezi_ch-4_p-2_s-8\",\"liezi_ch-4_p-2_s-9\",\"liezi_ch-4_p-2_s-10\",\"liezi_ch-4_p-2_s-11\",\"liezi_ch-4_p-2_s-12\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"道家高士亢倉子（庚桑楚）居住在陳國，有人向陳國國君報告稱讚亢倉子說：亢倉子領悟掌握了老子的至高大道，能夠用耳朵看見事物、用眼睛聆聽聲音（以耳視而目聽）！陳侯感到無比奇異神妙，派遣使者備辦豐厚禮品重金聘請他入宮。亢倉子抵達後，陳侯迫不及待詢問他這門神奇的法術。亢倉子回答說：外面流傳傳言的人完全是在胡說八道妄言傳播啊！我只能做到使自己的視覺聽覺感官在精神深層相互融會貫通（耳目相通），而絕不可能做到違背生理結構讓耳朵直接代替眼睛去看、讓眼睛代替耳朵去聽（代用）！陳侯追問道：如果是這樣，那這究竟是怎樣一種神妙境界呢？亢倉子回答說：我的身體達到了精神高度凝定集中、形體物質執念徹底解脫放下的境界，骨骼血肉完全融化於大道造化之中。我已經完全感覺不到身軀所寄託的居所，感覺不到雙腳所踩踏的土地，感覺不到內心所思考的意念，感覺不到言語所包藏的機巧。眼睛如同耳朵一樣靈敏，耳朵如同鼻子一樣通透，鼻子如同嘴巴一樣感知，所有感官在精神層面無所不同。天下的一切事物到來，沒有不能瞬間融通理解的，沒有不能精準洞察洞悉的。這就是我所說的耳目相通的真諦啊！\",\"analysis\":\"【篇旨與亢倉子闢謠耳視目聽感官互通心理學】亢倉子向陳侯闢謠「以耳視目聽」的江湖迷信傳言，從心性生理學角度科學解釋「耳目相通」乃是「心凝形釋、通感直覺」的高階認知融合狀態。\\\\n【詞義訓詁】「傳者妄也」：破除神怪迷信傳言；「耳目相通非代用」：否定反生理常識的特異功能，確立認知通感原理；「骨肉都融」：身心高度放鬆、天人合一。\\\\n【科學唯物主義】以科學理性的態度解構特異功能迷信，將其還原為人類高階專注與直覺洞察力的心理認知現象。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-4_p-3\",\"chapterId\":\"liezi_ch-4\",\"order\":3,\"canonicalText\":\"商丘開見老商氏，老商氏不言。商丘開三年侍之，無所得。乃往見伯高子，伯高子亦不言。商丘開復侍之三年，亦無所得。乃自省曰：「道在於己，不在於人。」退而居山，獨坐修養。三年之後，大悟。復見老商氏、伯高子，二子迎而笑曰：「子得之矣！」故曰：至道無言，至德無跡。求諸人者遠，求諸己者近。\",\"sentenceIds\":[\"liezi_ch-4_p-3_s-1\",\"liezi_ch-4_p-3_s-2\",\"liezi_ch-4_p-3_s-3\",\"liezi_ch-4_p-3_s-4\",\"liezi_ch-4_p-3_s-5\",\"liezi_ch-4_p-3_s-6\",\"liezi_ch-4_p-3_s-7\",\"liezi_ch-4_p-3_s-8\",\"liezi_ch-4_p-3_s-9\",\"liezi_ch-4_p-3_s-10\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"商丘開前去拜見大師老商氏求道，老商氏整天閉口不言一句話也不說。商丘開侍奉了老商氏整整三年，什麼具體祕術都沒有得到。於是他轉而前往拜見伯高子，伯高子同樣終日靜默一言不發。商丘開又侍奉了伯高子整整三年，依然什麼具體言論都沒有得到。商丘開於是深刻自我反省道：真理大道原來完全在於我自己的內心修證，而根本不在於向外人苦苦乞求啊！於是他毅然退隱居處在深山之中，獨自一人靜坐修養心性。三年之後，他徹底大徹大悟！當他重新前去拜見老商氏與伯高子時，兩位大師遠遠迎接著他相視大笑說：你現在終於真正得道了！所以古人說：至高無上的大道超越了言語文字的表達（至道無言），至高無上的道德不留下任何矯飾做作的痕跡（至德無跡）。向外人盲目乞求的人只會離真理越來越遙遠，向內在反求自省的人才能離真理越來越親近！\",\"analysis\":\"【篇旨與商丘開求道九年反求諸己至道無言】記錄商丘開侍奉老商、伯高六年不言，最終回歸深山自省頓悟之公案，確立「道在於己不在於人、至道無言求諸己近」的內在超越論。\\\\n【詞義訓詁】「不言」：不立文字、以心傳心之禪道教學法；「大悟」：打破向外追逐的執念、回歸自性本體；「求諸人者遠」：向外馳求必入歧途。\\\\n【自力覺悟】強調真正的智慧與真理無法由外界直接灌輸，必須依靠個體深度的自我反省與生命實踐方能覺醒。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-4_p-4\",\"chapterId\":\"liezi_ch-4\",\"order\":4,\"canonicalText\":\"子列子問於關尹曰：「至人之言，若響之應聲，若影之隨形。何其神也？」關尹曰：「非神也，理自然也。夫響不求聲，而聲至則應；影不求形，而形至則隨。至人虛己以應物，不為物先，不為物後，故能無不應。若有心於應，則有不應矣。」\",\"sentenceIds\":[\"liezi_ch-4_p-4_s-1\",\"liezi_ch-4_p-4_s-2\",\"liezi_ch-4_p-4_s-3\",\"liezi_ch-4_p-4_s-4\",\"liezi_ch-4_p-4_s-5\",\"liezi_ch-4_p-4_s-6\",\"liezi_ch-4_p-4_s-7\",\"liezi_ch-4_p-4_s-8\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"列子向關尹子請教道：得道的至人開口說話與應對萬事，就如同回聲響應聲音一樣精準迅速，如同影子跟隨形體一樣自然緊密。這究竟為什麼會如此神奇神妙呢？關尹子回答說：這絕非什麼怪力亂神的神通，而是事物發展演化的自然規律罷了！那回聲從來不主動去追求聲音，但外界聲音一旦發出回聲就自然呼應；那影子從來不主動去追求形體，但形體一旦出現影子就自然跟隨。至人清空自身的成見私欲（虛己）來精準應對萬物，不搶在事物之前盲目主觀妄動，不落在事物之後遲鈍拖延，所以能夠做到無所不精準響應。如果內心懷有主觀偏私的企圖心去刻意響應，那就必然會出現嚴重失誤與無法響應的困局了！\",\"analysis\":\"【篇旨與虛己應物響應聲影隨形感應哲學】闡發道家「虛己應物、不先不後」的感應哲學——以影隨形、響應聲為喻，論證徹底放下主觀偏見（虛己）方能達到最高的客觀應變力。\\\\n【詞義訓詁】「非神也理自然也」：徹底破除神祕主義迷信，歸結為客觀自然規律；「虛己以應物」：排除自我執念以客觀反映真實情況；「有心於應則不應」：主觀預設必導致決策偏差。\\\\n【現代決策與溝通】在快速變化的環境中，保持開放透明的心態（虛己）、不預設偏見，方能對市場與危機做出最精準敏捷的響應。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-4_p-5\",\"chapterId\":\"liezi_ch-4\",\"order\":5,\"canonicalText\":\"孔子窮於陳、蔡之間，七日不嘗粒，絃歌不絕。子路入見曰：「夫子之道，蓋窮矣？」孔子曰：「由！夫芝蘭生於深林，不以無人而不芳；君子修道立德，不以窮困而改節。命也夫！知其不可奈何而安之若命，此君子之所以為君子也。」\",\"sentenceIds\":[\"liezi_ch-4_p-5_s-1\",\"liezi_ch-4_p-5_s-2\",\"liezi_ch-4_p-5_s-3\",\"liezi_ch-4_p-5_s-4\",\"liezi_ch-4_p-5_s-5\",\"liezi_ch-4_p-5_s-6\",\"liezi_ch-4_p-5_s-7\",\"liezi_ch-4_p-5_s-8\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"孔子率領弟子們被圍困在陳國與蔡國之間的荒野荒原之上，連續整整七天七夜沒有喫上一粒糧食（七日不嘗粒），然而孔子在帳篷中依然彈琴講學絃歌之聲不絕於耳。子路走進來憤憤不平地問道：先生推行的大道，難道已經徹底走到走投無路的絕境了嗎？孔子平靜地回答說：仲由啊！那高貴芬芳的芝草幽蘭生長在深山密林之中，絕不會因為沒有人前來欣賞觀看就不散發自己的清香；有德君子修養大道樹立品德，絕不會因為身處窮困厄境就改變自己的道德節操！這一切都是時代與命運的考驗啊！深知某些客觀歷史逆境無法憑一己之力強行扭轉，從而泰然處之、安於其中心如止水堅守正道，這正是君子之所以能夠成為君子的根本原因啊！\",\"analysis\":\"【篇旨與陳蔡之厄芝蘭生於深林不改其節】記錄孔子在陳蔡絕糧困境中以「芝蘭生深林不以無人不芳」激勵弟子，確立君子在極端逆境中「安之若命、不改其節」的崇高氣節。\\\\n【詞義訓詁】「七日不嘗粒」：陳蔡絕糧生死考驗；「芝蘭不以無人不芳」：道德追求具有絕對的內在自足性，不依賴外界評價與獎賞；「不以窮困改節」：窮且益堅、不墜青雲之志。\\\\n【人格典範】無論外界環境多麼黑暗惡劣，內在良知與理想光芒永遠獨立綻放，成就中華民族最堅韌的精神脊樑。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-4_p-6\",\"chapterId\":\"liezi_ch-4\",\"order\":6,\"canonicalText\":\"子列子學也，三年之後，心不敢念是非，口不敢言利害，始得老商一眄而已。五年之後，心更念是非，口更言利害，老商始一解顏而笑。七年之後，從心之所念，更無是非；從口之所言，更無利害。夫子始一引吾並席而坐。九年之後，橫心之所念，橫口之所言，亦不知我之是非利害歟，亦不知彼之是非利害歟，外內進矣。而後眼如耳，耳如鼻，鼻如口，口無不同。心凝形釋骨肉都融；不覺形之所倚，足之所履，心之所念，言之所藏。如斯而已。則理無所隱矣。\",\"sentenceIds\":[\"liezi_ch-4_p-6_s-1\",\"liezi_ch-4_p-6_s-2\",\"liezi_ch-4_p-6_s-3\",\"liezi_ch-4_p-6_s-4\",\"liezi_ch-4_p-6_s-5\",\"liezi_ch-4_p-6_s-6\",\"liezi_ch-4_p-6_s-7\",\"liezi_ch-4_p-6_s-8\",\"liezi_ch-4_p-6_s-9\",\"liezi_ch-4_p-6_s-10\",\"liezi_ch-4_p-6_s-11\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"列子求道學習的時候，經過了三年的時間，心裡不敢去分辨是與非，嘴上不敢去談論利與害，這才換得老師老商斜著眼睛看他一眼而已。又過了五年，心裡再次去思考是與非，嘴上再次去談論利與害，老商這才第一次放開臉面露出了笑容。又過了七年，順從心裡所想的，卻發現根本沒有什麼是與非；順從嘴上所說的，也發現根本沒有什麼利與害，這時老師才第一次拉著我與他並排坐在同一個席子上。到了第九年，無論心裡怎麼隨意去想，無論嘴上怎麼隨意去說，既不知道什麼是我的是非利害，也不知道什麼是他人的是非利害，自身與外物已經完全融為一體了。在這之後，眼睛的作用變得像耳朵一樣，耳朵像鼻子一樣，鼻子像嘴巴一樣，所有感官的功能都混同無異了。心神凝聚而形體彷彿消散，骨肉都融化於虛空之中；感覺不到身體倚靠著什麼，感覺不到腳下踩著什麼，感覺不到心裡在想什麼，也感覺不到言語裡包含了什麼。達到了這樣的境界而已，那麼大道的真理也就沒有什麼隱藏的了。\",\"analysis\":\"【訓詁與名物】：「老商」列子的老師。「眄（miǎn）」斜視，表示輕視或不以為然。「解顏」舒展面容。「引吾並席而坐」拉著我同坐一席，表示極大的認可與親近。「橫（héng）」隨意、放縱。「外內進矣」物與我（外與內）的界限都消失了。「心凝形釋」心神凝聚專一，形體彷彿解除消散。「履」踩踏。\\\\n\\\\n【章法與結構】：本段以時間為軸（三年、五年、七年、九年），層層遞進地描寫了列子修道的四個階段及其老師老商的四次反饋（一眄、解顏笑、並席坐、無記載的默契），最後描述了修道大成後物我兩忘、感官互通的神奇境界。結構極其嚴密，具有強烈的修行次第感。\\\\n\\\\n【思想與義理】：這是一段描寫道家修煉次第與極高境界的千古名篇。列子的修行經歷了「刻意壓抑是非（不敢）——重新面對是非（更念）——超越是非（無是非）——徹底忘卻是非物我（不知我彼）」的否定之否定過程。這說明真正的「道」不是靠強行壓制人性得來的，而是要在經歷世俗後徹底超越世俗的二元對立（是非、利害、物我）。當修行達到第九年的極致時，列子體驗到了「心凝形釋骨肉都融」的「坐忘」境界，感官的界限被打破（眼如耳），主客體的對立徹底消解，人與宇宙大道完全融為一體。這種渾然忘我、無拘無束的精神自由，正是道家修行的最高目標。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-4_p-7\",\"chapterId\":\"liezi_ch-4\",\"order\":7,\"canonicalText\":\"初子列子好遊。壺丘子曰：「禦寇好遊，遊何所好？」列子曰：「遊之樂，所玩無故。人之遊也，觀其所見；我之遊也，觀其所變。遊乎遊乎！未有能辨其遊者。」壺丘子曰：「禦寇之遊固與人同歟，而曰固與人異歟？凡所見，亦恆見其變。玩彼物之無故，不知我亦無故。務外遊，不知務內觀。外遊者，求備於物；內觀者，取足於身。取足於身，遊之至也；求備於物，遊之不至也。」於是列子終身不出，自以為不知遊。壺丘子曰：「遊其至乎！至遊者不知所適；至觀者不知所眡，物物皆遊矣，物物皆觀矣，是我之所謂遊，是我之所謂觀也。故曰：遊其至矣乎！遊其至矣乎！」\",\"sentenceIds\":[\"liezi_ch-4_p-7_s-1\",\"liezi_ch-4_p-7_s-2\",\"liezi_ch-4_p-7_s-3\",\"liezi_ch-4_p-7_s-4\",\"liezi_ch-4_p-7_s-5\",\"liezi_ch-4_p-7_s-6\",\"liezi_ch-4_p-7_s-7\",\"liezi_ch-4_p-7_s-8\",\"liezi_ch-4_p-7_s-9\",\"liezi_ch-4_p-7_s-10\",\"liezi_ch-4_p-7_s-11\",\"liezi_ch-4_p-7_s-12\",\"liezi_ch-4_p-7_s-13\",\"liezi_ch-4_p-7_s-14\",\"liezi_ch-4_p-7_s-15\",\"liezi_ch-4_p-7_s-16\",\"liezi_ch-4_p-7_s-17\",\"liezi_ch-4_p-7_s-18\",\"liezi_ch-4_p-7_s-19\",\"liezi_ch-4_p-7_s-20\",\"liezi_ch-4_p-7_s-21\",\"liezi_ch-4_p-7_s-22\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"起初列子非常喜好出門遠遊。老師壺丘子問道：禦寇你如此喜好出門旅遊，這旅遊之中究竟有什麼讓你如此喜好的呢？列子回答說：旅遊的快樂，在於所欣賞玩味的一切事物永遠沒有重複陳舊（所玩無故）。普通世俗之人的旅遊，只不過是走馬觀花觀賞他們眼前看見的景物；而我的旅遊，是在深沉觀察萬事萬物千變萬化的動態規律（觀其所變）。旅遊啊旅遊！世間還從來沒有誰能真正理解我這種高雅的旅遊境界呢！壺丘子指點他說：禦寇啊，你的旅遊本質上同普通人完全相同，怎麼能狂妄地說自己的旅遊同別人截然不同呢？凡是眼睛所看見的景物，本來就無時無刻不在變化之中。你沉溺於玩味外在萬物的新奇不陳舊，卻完全不知道我們自我生命身心同樣也是無時無刻不在變化更新！你一心只知道致力於向外奔波旅遊（務外遊），卻完全不知道致力於向內在心靈進行觀照自省（務內觀）！向外旅遊的人，永遠在向外在物質世界乞求滿足完備；向內觀照的人，在自身內在生命本性中就能獲得圓滿自足。在自身生命中獲得自足，這才是旅遊的最高極致境界；向外在物質乞求滿足，那是根本沒有觸及旅遊真諦的淺陋層次啊！列子聽後大受震動，自此之後終身閉門不出，自認過去根本不懂得什麼是真正的旅遊。壺丘子稱讚道：這才是達到了旅遊的最高境界啊！真正達到最高至遊境界的人，心中根本沒有非去不可的目的地；真正達到最高至觀境界的人，眼中根本沒有刻意死盯的具體景物。世間萬事萬物無時無刻不在逍遙至遊，世間萬事萬物無處不可深刻觀照，這才是我所說的至遊，這才是我所說的至觀啊！所以說：這才是旅遊的最高極致境界啊！這才是旅遊的最高極致境界啊！\",\"analysis\":\"【篇旨與外遊求備於物內觀取足於身至遊至觀美學哲學】先秦美學與心靈旅行最高傑作——壺丘子批判列子「觀其所變」仍屬「務外遊（求備於物）」，確立「務內觀（取足於身、至遊不知所適）」的內在精神自由美學。\\\\n【詞義訓詁】「所玩無故」：故，陳舊；追求外在景觀的新奇不重複；「外遊求備於物，內觀取足於身」：向外索取物質刺激 vs 向內涵養精神自足；「至遊不知所適」：心靈自由超越物理空間移動局限。\\\\n【精神美學】最高級的旅行不是走遍萬水千山的物理位移，而是心靈深處的覺醒與向內觀照。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-4_p-8\",\"chapterId\":\"liezi_ch-4\",\"order\":8,\"canonicalText\":\"龍叔謂文摯曰：「子之術微矣。吾有疾，子能已乎？」文摯曰：「唯命所聽。然先言子所病之證。」龍叔曰：「吾鄉譽不以為榮，國毀不以為辱；得而不喜，失而弗憂；視生如死，視富如貧，視人如豕，視吾如人。處吾之家，如逆旅之舍；觀吾之鄉，如戎蠻之國。凡此眾庶，爵賞不能勸，刑罰不能威，盛衰利害不能易，哀樂不能移。固不可事國君，交親友，御妻子，制僕隸。此奚疾哉？奚方能已之乎？」文摯乃命龍叔背明而立。文摯自後嚮明而望之，既而曰：「嘻！吾見子之心矣，方寸之地虛矣，幾聖人也！子心六孔流通，一孔不達。今以聖智為疾者，或由此乎！非吾淺術所能已也。」\",\"sentenceIds\":[\"liezi_ch-4_p-8_s-1\",\"liezi_ch-4_p-8_s-2\",\"liezi_ch-4_p-8_s-3\",\"liezi_ch-4_p-8_s-4\",\"liezi_ch-4_p-8_s-5\",\"liezi_ch-4_p-8_s-6\",\"liezi_ch-4_p-8_s-7\",\"liezi_ch-4_p-8_s-8\",\"liezi_ch-4_p-8_s-9\",\"liezi_ch-4_p-8_s-10\",\"liezi_ch-4_p-8_s-11\",\"liezi_ch-4_p-8_s-12\",\"liezi_ch-4_p-8_s-13\",\"liezi_ch-4_p-8_s-14\",\"liezi_ch-4_p-8_s-15\",\"liezi_ch-4_p-8_s-16\",\"liezi_ch-4_p-8_s-17\",\"liezi_ch-4_p-8_s-18\",\"liezi_ch-4_p-8_s-19\",\"liezi_ch-4_p-8_s-20\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"龍叔向名醫文摯請教說：您的醫術精深微妙極了。我現在身患重病，您能將我的病徹底治癒嗎？文摯說：一切聽從您的吩咐。但請您先詳細說說您患病的具體症狀。龍叔說：我獲得全鄉人的讚譽卻絲毫不感到光榮，遭受全體國人的詆毀誹謗卻絲毫不感到恥辱；得到巨大利益財富絲毫不感到欣喜，丟失了資產財富也絲毫不感到憂愁；看待活著同看待死亡完全一樣，看待富貴同看待貧賤完全一樣，看待世俗眾人如同看待奔跑的豬豕，看待我自己也不過如同看待一個普通凡人；居處在我自己的家中，感覺就如同暫住在簡陋的旅店客棧一樣；觀看我自己的故鄉家鄉，感覺就如同看待未開化的戎狄蠻荒之國一樣。面對這世俗的一切人事物，官爵賞賜無法激勵勸勉我，酷刑懲罰無法威嚇恐懼我，興盛衰亡利害得失無法改變我，悲哀狂喜無法動搖我。像我這樣的心態，自然無法再去侍奉國家君王，無法再去結交至親朋友，無法再去管教妻子兒女，也無法再去統治驅使僕役奴隸了。我這究竟是得了什麼怪病啊？究竟有什麼藥方能把我的病治好呢？名醫文摯於是命令龍叔背對著光亮站立。文摯從他身後迎著光亮仔細透視觀察他的心臟五臟，過了一會兒驚呼道：哎呀！我已經清清楚楚看透您的內心了！您胸中方寸之地純虛無垢，簡直已經接近至高聖人的境界了！您的心靈七孔之中已有六孔徹底融會貫通，唯獨只剩最後一孔尚未完全通達罷了。如今您竟然把至高聖人的卓越智慧當作嚴重疾病，或許正是因為這最後一孔未通所致吧！這等超越凡俗的聖人境界，絕非我這等淺陋的世俗醫術所能夠醫治得了的啊！\",\"analysis\":\"【篇旨與龍叔問疾文摯透視心六孔流通以聖智為疾】極具諷刺與解構色彩之神醫心理寓言——龍叔看破世俗毀譽榮辱、名利爵賞，反自以為患病求醫，名醫文摯透視其心指出「六孔流通虛明若聖」，批判世俗病態社會將覺醒者視為病人。\\\\n【詞義訓詁】「方寸之地虛矣」：方寸，指心臟；心靈徹底排除名利私欲雜質；「六孔流通一孔不達」：通曉世俗虛妄卻尚未達到完全融通自在之化境；「以聖智為疾」：覺醒者在病態社會中遭受的異化困境。\\\\n【反思哲學】當整個社會都陷入功利狂熱時，保持清醒與超然的智者往往會被世俗誤判為異類或病人。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-4_p-9\",\"chapterId\":\"liezi_ch-4\",\"order\":9,\"canonicalText\":\"無所由而常生者，道也。由生而生，故雖終而不亡，常也；由生而亡，不幸也。有所由而常死者，亦道也。由死而死，故雖未終而自亡者，亦常；由死而生，幸也。故無用而生謂之道，用道得終謂之常；有所用而死者亦謂之道，用道而得死者亦謂之常。\",\"sentenceIds\":[\"liezi_ch-4_p-9_s-1\",\"liezi_ch-4_p-9_s-2\",\"liezi_ch-4_p-9_s-3\",\"liezi_ch-4_p-9_s-4\",\"liezi_ch-4_p-9_s-5\",\"liezi_ch-4_p-9_s-6\",\"liezi_ch-4_p-9_s-7\",\"liezi_ch-4_p-9_s-8\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"不依賴任何外在原因條件而恆常長生永存的，正是真理大道。遵循生命大道的規律而繁衍生長，所以縱然肉身壽終正寢而精神道統永不消亡，這是生命的恆常正道；若因為人為妄動而在生命中過早夭亡，這就是生命的不幸悲劇。順應生死規律而平靜迎來必然的死亡，這同樣符合天道自然。遵循大自然規律而走向命運終局，所以縱然尚未達到最高壽數而自然老死，這同樣屬於自然的常道；在瀕臨死亡絕境中因契合大道而重新獲得新生，這是命運的慶幸。所以不帶功利造作而自然生發就叫做合乎大道，運用大道規律保全天年壽終正寢就叫做順應常道；順應自然使命而平靜迎來死亡同樣叫做合乎大道，依循大道規律而平靜完成生命歸宿同樣叫做順應常道。\",\"analysis\":\"【篇旨與常生常死道之自然生死辯證論】深刻辨析「生生之常」與「生死之道」，確立順應自然生長與接納必然死亡皆符合大道規律的客觀唯物主義生死觀。\\\\n【詞義訓詁】「無所由而常生」：大道超越因果條件之自足永恆性；「用道得終」：順應規律保全天賦壽命、壽終正寢；「用道得死」：平靜尊嚴地接納死亡。\\\\n【生死哲理】消解對生命的過度執著與對死亡的恐懼，確立生死皆為大道演化自然環節的豁達觀念。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-4_p-10\",\"chapterId\":\"liezi_ch-4\",\"order\":10,\"canonicalText\":\"季梁之死，楊朱望其門而歌；隨梧之死，楊朱撫其屍而哭。隸人之生，隸人之死，眾人且歌，眾人且哭。人情之感，隨時而異，君子順自然之變，不以世俗之禮拘其心。\",\"sentenceIds\":[\"liezi_ch-4_p-10_s-1\",\"liezi_ch-4_p-10_s-2\",\"liezi_ch-4_p-10_s-3\",\"liezi_ch-4_p-10_s-4\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"當通達生死的大師季梁去世之際，哲學家楊朱遠遠望著他的家門放聲高歌祝賀他回歸大道；而當摯友隨梧不幸去世之時，楊朱卻趴在他的遺體上撫屍痛哭哀悼。面對普通僕役奴隸的降生與死去，世俗大眾時而隨波逐流跟著唱歌慶賀，時而隨波逐流跟著嚎啕痛哭。人類內心情感的自然流露與感應，原本就是隨著具體情境與生命因緣而各不相同的；真正君子順應大自然的演化變化，絕不用世俗僵化的教條禮儀來強行束縛禁錮自己的真誠心靈！\",\"analysis\":\"【篇旨與楊朱歌哭無常真情流露反禮教教條】記錄楊朱對季梁之死「望門而歌」、對隨梧之死「撫屍而哭」的不同表現，確立「順自然之變、不拘世俗禮法」的真實性情倫理。\\\\n【詞義訓詁】「望門而歌」：祝賀通達之士回歸大道家園；「撫屍而哭」：痛惜摯友離世的真情自然流露；「不以世俗之禮拘心」：打破偽善僵化的禮教表演。\\\\n【生命真誠性】反對將喪葬禮儀異化為虛偽表演，倡導尊重個體發自內心的真實情感表達。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-4_p-11\",\"chapterId\":\"liezi_ch-4\",\"order\":11,\"canonicalText\":\"目將眇者先睹秋毫，耳將聾者先聞蚋飛，口將爽者先辨淄澠，鼻將窒者先覺焦朽，體將僵者先亟奔佚，心將迷者先識是非。故物不至者則不反。\",\"sentenceIds\":[\"liezi_ch-4_p-11_s-1\",\"liezi_ch-4_p-11_s-2\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"雙眼即將失明瞎掉的人，在失明前夕往往會突然看清極其微細的秋毫（迴光返照）；雙耳即將耳聾失聰的人，在耳聾前夕往往會突然清晰聽見微小蚊蟲的飛鳴之聲；嘴巴味覺即將敗壞失味的人，在失味前夕往往能極度敏銳分辨淄水與澠水的微小水質差異；鼻子嗅覺即將堵塞喪失的人，在堵塞前夕往往能格外靈敏察覺微弱的焦糊腐朽之氣；身體即將僵硬中風癱瘓的人，在發病前夕往往會突然精神亢奮狂奔飛跑；心智即將陷入狂躁迷亂的人，在發瘋前夕往往會格外自負地大談是非曲直。所以事物如果沒有發展演化到極點，就絕對不會走向反面（物極必反）！\",\"analysis\":\"【篇旨與物極必反亢極必衰病理預兆六候】以眼、耳、口、鼻、體、心六大感官功能在崩潰前夕呈現出的「異常亢奮迴光返照」為精闢病理生理學例證，深刻揭示「物不至者則不反、物極必反」的普遍規律。\\\\n【詞義訓詁】「眇」：音秒，一目失明或雙目失明；「爽」：差錯、功能衰退喪失；「辨淄澠」：辨別淄水與澠水微小水質差異；「物不至則不反」：發展未達極點則不會發生質變反轉。\\\\n【系統危機預警】任何系統（人體、社會、經濟）在崩潰前夕往往會出現短暫的異常繁榮與超常亢奮，具備深刻的危機預警價值。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-4_p-12\",\"chapterId\":\"liezi_ch-4\",\"order\":12,\"canonicalText\":\"鄭之圃澤多賢，東裏多才。圃澤之役有伯豐子者，行過東裏，遇鄧析。鄧析顧其徒而笑曰：「為若舞彼來者奚若？」其徒曰：「所願知也。」鄧析謂伯豐子曰：「汝知養養之義乎？受人養而不能自養者，犬豕之類也；養物而物為我用者，人之力也。使汝之徒，食而飽，衣而息，執政之功也。長幼羣聚，而為牢藉庖廚之物，奚異犬豕之類乎？」伯豐子不應。伯豐子之從者越次而進曰：「大夫不聞齊魯之多機乎？有善治土木者，有善治金革者，有善治聲樂者，有善治書數者，有善治軍旅者，有善治宗廟者，羣才備也。而無相位者，無能相使者。而位之者無知，使之者無能，而知之與能，為之使焉。執政者迺吾之所使，子奚矜焉？」鄧析無以應，目其徒而退。\",\"sentenceIds\":[\"liezi_ch-4_p-12_s-1\",\"liezi_ch-4_p-12_s-2\",\"liezi_ch-4_p-12_s-3\",\"liezi_ch-4_p-12_s-4\",\"liezi_ch-4_p-12_s-5\",\"liezi_ch-4_p-12_s-6\",\"liezi_ch-4_p-12_s-7\",\"liezi_ch-4_p-12_s-8\",\"liezi_ch-4_p-12_s-9\",\"liezi_ch-4_p-12_s-10\",\"liezi_ch-4_p-12_s-11\",\"liezi_ch-4_p-12_s-12\",\"liezi_ch-4_p-12_s-13\",\"liezi_ch-4_p-12_s-14\",\"liezi_ch-4_p-12_s-15\",\"liezi_ch-4_p-12_s-16\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"鄭國的圃田郊澤聚集著眾多隱逸賢達，鄭國的東裏貴族城區聚集著眾多仕途才俊。圃田隱士中有一個名叫伯豐子的人，步行路過東裏城區時，偶遇了名家辯論大師鄧析。鄧析回頭對自己的門徒弟子們笑著說：我替你們當面戲弄調侃一下那個走過來的鄉巴佬，怎麼樣？弟子們起鬨說：我們很想開開眼界！鄧析走上前對伯豐子挑釁道：你懂得供養與被供養的深層大義嗎？接受別人的供養而自身沒有能力自食其力的人，不過是與豬狗禽獸同類罷了；能夠養育統治天下萬物並使萬物為我所用的人，才是人類智慧力量的展現。讓你們這些下層賤民，每天有飯喫能喫飽，有衣服穿能休息，這全都是我們執政貴族的偉大功績啊！你們老老少少羣聚在一起，隨時充當國家牢獄徵稅與廚房役使的工具，這跟圈養在豬圈裡的豬狗禽獸又有什麼區別呢？伯豐子神色平靜不屑於回答。這時伯豐子身邊跟隨的一位隨從弟子跨前一步上前反駁道：大夫難道沒有聽說過齊國與魯國具備眾多專業技能人才嗎？那裡有精通土木工程建築的大師，有精通金屬冶煉皮甲製造的專家，有精通音樂宮律的樂師，有精通文獻歷史與數學計算的學者，有精通軍旅排兵布陣的將領，有精通宗廟祭祀禮儀的專家，各類專業人才一應俱全！然而在他們之中，卻沒有誰身居宰相高位，沒有誰去發號施令役使他人。而身居統治高位發號施令的人往往自身毫無具體專業知識，驅使使喚群臣的人往往自身毫無具體動手技能；但天下真正具備智慧與專業技能的人才，卻不得不接受他們的統治使喚。因此，你們這些所謂的執政貴族，本質上只不過是我們廣大勞動者與專業人才僱傭用來維持秩序的僕役罷了，你又有什麼好盲目傲慢自誇的呢！鄧析被駁斥得啞口無言無言以對，只能尷尬地給弟子們使了個眼色狼狽退下。\",\"analysis\":\"【篇旨與伯豐子隨從舌戰鄧析勞心與勞力社會分工論】先秦辯論史上最精彩的階級批判與反精英傲慢公案——名家鄧析以「執政者養民、民如犬豕」辱罵底層，伯豐子隨從以「執政者無知無能、乃吾之所使」予以降維打擊。\\\\n【詞義訓詁】「牢藉庖廚」：牢，牛羊圈；藉，供品祭牲；比喻底層百姓淪為統治者隨意宰割之工具；「執政者迺吾之所使」：極具現代民主主權在民與公僕意識之震撼金句。\\\\n【政治哲學震撼】深刻顛覆「勞心者治人、勞力者治於人」的剝削階級偏見，確立勞動大眾與專業技術人員才是社會財富真正創造者、統治者本質上是社會服務者的進步公僕觀。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-4_p-13\",\"chapterId\":\"liezi_ch-4\",\"order\":13,\"canonicalText\":\"公儀伯以力聞諸侯，堂谿公言之於周宣王，王備禮以聘之。公儀伯至，觀形，懦夫也。宣王心惑而疑曰：「女之力何如？」公儀伯曰：「臣之力能折春螽之股，堪秋蟬之翼。」王作色曰：「吾之力者能裂犀兕之革，曳九牛之尾，猶憾其弱。女折春螽之股，堪秋蟬之翼，而力聞天下，何也？」公儀伯長息退席曰：「善哉，王之問也！臣敢以實對。臣之師有商丘子者，力無敵於天下，而六親不知，以未嘗用其力故也。臣以死事之。乃告臣曰：『人慾見其所不見，視人所不窺；欲得其所不得，修人所不為。故學眎者先見輿薪，學聽者先聞撞鍾。夫有易於內者，無難於外。於外無難，故名不出其一道。』今臣之名聞於諸侯，是臣違師之教，顯臣之能者也。然則臣之名不以負其力者也，以能用其力者也，不猶愈於負其力者乎？」\",\"sentenceIds\":[\"liezi_ch-4_p-13_s-1\",\"liezi_ch-4_p-13_s-2\",\"liezi_ch-4_p-13_s-3\",\"liezi_ch-4_p-13_s-4\",\"liezi_ch-4_p-13_s-5\",\"liezi_ch-4_p-13_s-6\",\"liezi_ch-4_p-13_s-7\",\"liezi_ch-4_p-13_s-8\",\"liezi_ch-4_p-13_s-9\",\"liezi_ch-4_p-13_s-10\",\"liezi_ch-4_p-13_s-11\",\"liezi_ch-4_p-13_s-12\",\"liezi_ch-4_p-13_s-13\",\"liezi_ch-4_p-13_s-14\",\"liezi_ch-4_p-13_s-15\",\"liezi_ch-4_p-13_s-16\",\"liezi_ch-4_p-13_s-17\",\"liezi_ch-4_p-13_s-18\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"公儀伯憑藉一身神力名揚列國諸侯，堂谿公在周宣王面前極力舉薦了他，宣王備辦隆重禮品親自聘請他入朝。公儀伯抵達宮廷後，宣王上下打量他的形體，發現他骨瘦如柴宛如一個弱不禁風的懦夫。宣王內心無比疑惑懷疑地問道：你的力氣究竟有多大呢？公儀伯回答說：微臣的力量，能夠折斷春天蝗蟲（春螽）的一條大腿，能夠承受秋天蟬蟲的一對薄翼。宣王勃然變色憤怒地說：寡人自身的力量，能夠徒手撕裂犀牛野兕的堅硬厚皮，能夠倒拉著九頭巨牛的尾巴讓牛倒退，寡人尚且遺憾自己的力量太過軟弱！你僅僅能折斷春蟲之腿、承受秋蟬之翼，卻能神力名揚全天下，這究竟是憑什麼呢？公儀伯長長嘆了一口氣，恭敬退出席位回答說：問得太好了，大王的提問切中了本質啊！微臣大膽以實情回答大王。微臣的老師名叫商丘子，他的神力天下無敵，然而連他身邊的父母六親都不知道他身懷絕技，這是因為他一生從來不盲目逞能使用蠻力的緣故啊！微臣當年以死相隨侍奉老師，老師才傳授我心法說：人若想看見別人看不見的隱微真相，就必須去觀察別人從不窺視的細節；若想獲得別人無法得到的超凡境界，就必須去修養別人不肯踐行的道德。所以學習視力的人首先要能看清滿車的柴薪，學習聽力的人首先要能聽清撞擊巨鐘的轟鳴。內在心性達到了極致的平易純真，外在面對萬物就永遠不會有任何艱難險阻；外在毫無阻礙，所以真正的盛名絕不會單單局限於某一種片面的技能手段。如今微臣神力的名聲流傳於諸侯之間，這恰恰說明微臣違背了恩師的教誨、過早顯露了自己的微薄技能啊！雖然如此，微臣的名聲並非依仗著像野獸一樣盲目炫耀負重蠻力，而是懂得如何精妙精準運用自身力量的道法，這難道不比那些單純依仗蠻力死拼的人更加高明得多了嗎！\",\"analysis\":\"【篇旨與公儀伯折螽股堪蟬翼巧力與蠻力之辨】以周宣王誇耀「撕犀皮曳九牛」之蠻力對比公儀伯「折螽股堪蟬翼」之巧力，揭示掌握力量運化規律（用其力）遠勝於盲目逞兇鬥狠（負其力）。\\\\n【詞義訓詁】「春螽」：螽，音忠，蝗蟲螽斯；「負其力」：依恃蠻力自負傲慢；「有易於內無難於外」：內在心性通達平易，外在處事自然圓融無礙。\\\\n【力量哲學】最高級的力量不是具有破壞性的肌肉暴力，而是精準調控、四兩撥千斤的控制力與分寸感。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-4_p-14\",\"chapterId\":\"liezi_ch-4\",\"order\":14,\"canonicalText\":\"中山公子牟者，魏國之賢公子也。好與賢人遊，不恤國事，而悅趙人公孫龍。樂正子輿之徒笑之。公子牟曰：「子何笑牟之悅公孫龍也？」子輿曰：「公孫龍之為人也，行無師，學無友，佞給而不中，漫衍而無家，好怪而妄言。欲惑人之心，屈人之口，與韓檀等肄之。」公子牟變容曰：「何子狀公孫龍之過歟？請聞其實。」子輿曰：「吾笑龍之詒孔穿，言『善射者，能令後鏃中前括，發發相及，矢矢相屬；前矢造準，而無絕落，後矢之括猶銜弦，視之若一焉。』孔穿駭之。龍曰：『此未其妙者。逢蒙之弟子曰鴻超，怒其妻而怖之。引烏號之弓，綦衛之箭，射其目。矢來注眸子，而眶不睫，矢隧地而塵不揚。』是豈智者之言與？」公子牟曰：「智者之言，固非愚者之所曉。後鏃中前括，鈞後於前。矢注眸子而眶不睫，盡矢之勢也。子何疑焉？」樂正子輿曰：「子龍之徒，焉得不飾其闕？吾又言其尤者。龍誑魏王曰：『有意不心。有指不至。有物不盡。有影不移。髮引千鈞。白馬非馬。孤犢未嘗有母。』其負類反倫，不可勝言也。」公子牟曰：「子不諭至言而以為尤也。尤其在子矣。夫無意則心同。無指則皆至。盡物者常有。影不移者，說在改也。髮引千鈞，勢至等也。白馬非馬，形名離也。孤犢未嘗有母，非孤犢也。」樂正子輿曰：「子以公孫龍於馬皆條也。設令發於餘竅，子亦將承之。」公子牟默然良久告退曰：「請待餘日，更謁子論。」\",\"sentenceIds\":[\"liezi_ch-4_p-14_s-1\",\"liezi_ch-4_p-14_s-2\",\"liezi_ch-4_p-14_s-3\",\"liezi_ch-4_p-14_s-4\",\"liezi_ch-4_p-14_s-5\",\"liezi_ch-4_p-14_s-6\",\"liezi_ch-4_p-14_s-7\",\"liezi_ch-4_p-14_s-8\",\"liezi_ch-4_p-14_s-9\",\"liezi_ch-4_p-14_s-10\",\"liezi_ch-4_p-14_s-11\",\"liezi_ch-4_p-14_s-12\",\"liezi_ch-4_p-14_s-13\",\"liezi_ch-4_p-14_s-14\",\"liezi_ch-4_p-14_s-15\",\"liezi_ch-4_p-14_s-16\",\"liezi_ch-4_p-14_s-17\",\"liezi_ch-4_p-14_s-18\",\"liezi_ch-4_p-14_s-19\",\"liezi_ch-4_p-14_s-20\",\"liezi_ch-4_p-14_s-21\",\"liezi_ch-4_p-14_s-22\",\"liezi_ch-4_p-14_s-23\",\"liezi_ch-4_p-14_s-24\",\"liezi_ch-4_p-14_s-25\",\"liezi_ch-4_p-14_s-26\",\"liezi_ch-4_p-14_s-27\",\"liezi_ch-4_p-14_s-28\",\"liezi_ch-4_p-14_s-29\",\"liezi_ch-4_p-14_s-30\",\"liezi_ch-4_p-14_s-31\",\"liezi_ch-4_p-14_s-32\",\"liezi_ch-4_p-14_s-33\",\"liezi_ch-4_p-14_s-34\",\"liezi_ch-4_p-14_s-35\",\"liezi_ch-4_p-14_s-36\",\"liezi_ch-4_p-14_s-37\",\"liezi_ch-4_p-14_s-38\",\"liezi_ch-4_p-14_s-39\",\"liezi_ch-4_p-14_s-40\",\"liezi_ch-4_p-14_s-41\",\"liezi_ch-4_p-14_s-42\",\"liezi_ch-4_p-14_s-43\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"中山公子牟，是魏國一位賢德的名門公子。他喜好同天下賢士交往遊歷，不願為繁雜國政所牽累，格外推崇喜愛趙國名辯大師公孫龍。儒家名士樂正子輿的一幫門徒弟子對此大加嘲笑。公子牟問道：你們為什麼要嘲笑我喜愛推崇公孫龍呢？樂正子輿說：公孫龍這個人的為人，行事沒有正統師承，治學沒有嚴肅道友，口齒伶俐巧言善辯卻切不中道德要害，言論漫無邊際荒誕不經缺乏自成一家的宗派，嗜好追求怪誕詭異而滿口大發妄言！整天只想著去迷惑世人的心智，在辯論中強詞奪理折服別人的口舌，同韓檀之流天天在搞這些無聊的狡辯把戲！公子牟神色嚴肅起來說：你為什麼把公孫龍描述得如此不堪過分呢？請讓我聽聽具體事實依據。子輿說：我嘲笑公孫龍當初欺騙糊弄孔子後人孔穿，吹噓說：真正善於射箭的神射手，能射出一支箭使後一支箭的箭鏃精準射中前一支箭的箭尾凹槽（後鏃中前括），箭箭相接如連珠，箭箭相連成一線；前面的箭剛射中靶心靶準，懸空而不掉落，後面的箭尾還在弓弦上銜著，遠遠看去就如同一條不絕的長線一樣！孔穿聽得目瞪口呆無比驚駭。公孫龍接著吹噓說：這還不算最神妙的呢！神箭手逢蒙的弟子名叫鴻超，有一次對妻子發怒想恐嚇嚇唬她，拉開烏號寶弓，搭上綦衛利箭，正對著妻子的眼珠射去。利箭呼嘯而來正中妻子的眼球表面，而妻子的眼眶眼皮竟然連眨都來不及眨一下，箭頭隨即自然垂直墜落到地上，連地上的塵土都沒有被震揚起來！這難道是有智慧的智者所能說出的正常話嗎？公子牟回答說：大智者的精微言論，本來就不是凡夫愚者所能輕易理解領悟的！後箭之鏃射中前箭之括，是因為前後箭矢的力道軌跡完全精準均等（鈞後於前）；箭頭觸及眼球而眼眶不眨，是因為神射手精確算盡了箭矢末端動能衰竭的極限態勢（盡矢之勢）。你又有什麼好懷疑的呢？樂正子輿說：你作為公孫龍的崇拜者，怎麼可能不替他的荒謬漏洞百般掩飾粉飾呢！我再說幾條他更離譜荒誕的狂言吧！公孫龍曾當面欺騙忽悠魏王說：有概念意識而不依賴肉體心臟（有意不心）；有指涉對象而實體無法窮盡抵達（有指不至）；有具體物質而物質世界永不消滅（有物不盡）；飛鳥的影子在移動中實質並未移動（有影不移）；一根細頭髮絲能夠懸掛吊起三萬斤的巨石重物（髮引千鈞）；白馬根本就不是馬（白馬非馬）；失去母親的孤牛犢從來就未曾有過母親（孤犢未嘗有母）！他這套顛倒概念邏輯、背叛常理倫常的詭辯，簡直多得數不勝數！公子牟從容反駁道：那是因為你根本無法理解這些至理名言的深邃邏輯，反而把它們當作荒謬過失！真正的荒謬偏狹恰恰在你自己的認知局限裡啊！所謂無意則心同，超越主觀私意則人心與道心相通；所謂無指則皆至，超越了狹隘概念指涉則能通達一切本質；所謂物不盡，是因為物質轉化循環常存；所謂影不移，其物理力學原理在於新影子的不斷生滅覆蓋（說在改也）；所謂髮引千鈞，其極限力學原理在於受力均勻達到絕對平衡（勢至等也）；所謂白馬非馬，是因為白代表顏色概念，馬代表形體概念，二者在概念邏輯範疇上是分立的（形名離也）；所謂孤犢未嘗有母，是因為一旦稱其為孤犢，在定義當下它就已經處於無母的孤立概念狀態了啊！樂正子輿見辯論不贏，便出言譏諷調侃道：你把公孫龍連馬屁都能吹得頭頭是道條條有理。假如他放個屁從別的孔竅冒出來，恐怕你也會全盤為他承擔辯護吧！公子牟聽後神色冷靜，沉默良久告退說：請改天等大家心平氣和之時，我再來同您探討這高深的邏輯哲理吧！\",\"analysis\":\"【篇旨與公孫龍名辯哲學公子牟舌戰樂正子輿先秦邏輯學巔峯】中國哲學史最精彩的名辯邏輯學大對決——子輿以常識經驗批判公孫龍「白馬非馬、影不移、髮引千鈞、孤犢無母」，公子牟以高階符號學、力學平衡與概念分析（形名離、說在改、勢至等）逐條給出嚴密哲學力學論證！\\\\n【詞義訓詁】「後鏃中前括」：極限連珠箭射術；「影不移說在改也」：同《墨子・經下》，影子運動實為新舊光影生滅更替；「髮引千鈞勢至等也」：材料力學極限受力點與應力均勻分佈；「白馬非馬形名離也」：內涵邏輯學區分「種概念（白馬）」與「屬概念（馬）」。\\\\n【邏輯學與科學哲學價值】先秦名家展現出不亞於古希臘芝諾悖論與亞裏士多德邏輯學的純粹概念思辨與理論物理學萌芽。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-4_p-15\",\"chapterId\":\"liezi_ch-4\",\"order\":15,\"canonicalText\":\"堯治天下五十年，不知天下治歟，不治歟？不知億兆之願戴己歟，不願戴己歟？顧問左右，左右不知；問外朝，外朝不知；問在野，在野不知。堯乃微服遊於康衢，聞兒童謠曰：「立我蒸民，莫匪爾極。不識不知，順帝之則。」堯喜問曰：「誰教爾為此言？」童兒曰：「我聞之大夫。」問大夫，大夫曰：「古詩也。」堯還宮，召舜，因禪以天下。舜不辭而受之。\",\"sentenceIds\":[\"liezi_ch-4_p-15_s-1\",\"liezi_ch-4_p-15_s-2\",\"liezi_ch-4_p-15_s-3\",\"liezi_ch-4_p-15_s-4\",\"liezi_ch-4_p-15_s-5\",\"liezi_ch-4_p-15_s-6\",\"liezi_ch-4_p-15_s-7\",\"liezi_ch-4_p-15_s-8\",\"liezi_ch-4_p-15_s-9\",\"liezi_ch-4_p-15_s-10\",\"liezi_ch-4_p-15_s-11\",\"liezi_ch-4_p-15_s-12\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"聖王唐堯治理天下長達五十年之久，他自己竟然不知道天下究竟治理好了呢，還是沒有治理好呢？不知道全天下億萬黎民百姓究竟是真心由衷愛戴擁護自己呢，還是並不情願愛戴擁護自己呢？他回頭詢問身邊的左右近臣侍從，左右近臣說不知道；前去詢問外廷朝堂的百官公卿，百官公卿也說不知道；前去詢問隱居在野的隱士高人，在野隱士同樣說不知道。於是唐堯換上平民粗布衣服微服私訪，漫步漫遊在繁華康莊大道（康衢）之上，忽然聽見街頭天真無邪的孩童們正在拍手歡唱童謠道：養育使我們繁衍生活的億萬平民百姓啊，無一不是順應遵循著您最高的中正法則。我們無憂無慮沒有機巧心機與算計知巧，自然而然順應效法著天帝大自然的客觀法則！唐堯無比欣喜走上前問道：是誰教給你們唱這首童謠的呀？孩童天真地說：我們是從一位長者大夫那裡聽來的。唐堯前去詢問那位大夫，大夫回答說：這是一首代代相傳的上古詩歌啊！唐堯返回宮廷，立刻召見虞舜，正式決定將天子之位與全天下禪讓給舜。舜深知天命民心所向，從容不推辭坦然接受了禪讓！\",\"analysis\":\"【篇旨與堯遊康衢童謠順帝之則無為而治最高境界】記錄帝堯治理五十年微服私訪康衢，聞童謠「不識不知，順帝之則」，確立「至治無跡、百姓日用而不知」的無為而治最高政治美學，並順利禪讓於舜。\\\\n【詞義訓詁】「康衢」：四通八達、繁華和諧之大道；「立我蒸民，莫匪爾極」：蒸民，眾民；極，中正之至德法則；「不識不知」：民風淳樸、無機心巧詐；「舜不辭而受之」：天命民心所歸，坦蕩擔當大任。\\\\n【政治美學】最高明的治理是讓社會在自然無感中良性運轉，領袖深藏若虛，百姓自得其樂。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"liezi_ch-4_p-16\",\"chapterId\":\"liezi_ch-4\",\"order\":16,\"canonicalText\":\"關尹喜曰：「在己無居，形物其著。其動若水，其靜若鏡，其應若響。故其道若物者也。物自違道，道不違物。善若道者，亦不用耳，亦不用目，亦不用力，亦不用心。欲若道而用視聽形智以求之，弗當矣。瞻之在前，忽焉在後；用之彌滿六虛，廢之莫知其所。亦非有心者所能得遠，亦非無心者所能得近。唯默而得之，而性成之者得之。知而亡情，能而不為，真知真能也。發無知，何能情？發不能，何能為？聚塊也，積塵也，雖無一而非理也。」\",\"sentenceIds\":[\"liezi_ch-4_p-16_s-1\",\"liezi_ch-4_p-16_s-2\",\"liezi_ch-4_p-16_s-3\",\"liezi_ch-4_p-16_s-4\",\"liezi_ch-4_p-16_s-5\",\"liezi_ch-4_p-16_s-6\",\"liezi_ch-4_p-16_s-7\",\"liezi_ch-4_p-16_s-8\",\"liezi_ch-4_p-16_s-9\",\"liezi_ch-4_p-16_s-10\",\"liezi_ch-4_p-16_s-11\",\"liezi_ch-4_p-16_s-12\",\"liezi_ch-4_p-16_s-13\",\"liezi_ch-4_p-16_s-14\",\"liezi_ch-4_p-16_s-15\"],\"sourceRefs\":[{\"label\":\"《列子》—中國哲學書電子化計劃\",\"edition\":\"楊伯峻《列子集釋》本\",\"location\":\"https://ctext.org/liezi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《列子》—維基文庫\",\"edition\":\"張湛《列子注》四部叢刊本\",\"location\":\"https://zh.wikisource.org/zh-hant/列子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"關尹子（尹喜）深沉總結道：在自己內心深處毫無執念與固執的成見（在己無居），外界萬事萬物的客觀形態自然會清晰映照呈現。行動時如同流水一樣順勢而動隨方就圓，安靜時如同明鏡一樣毫無遮蔽平靜映照，回應事物時如同空谷回聲一樣精準響應。所以遵循大道的人完全順應客觀萬物的自然本性。往往是萬物自己違背了大道，而大道從未主動違背排斥過任何萬物。真正善於體悟順應大道的人，不需要刻意依賴耳朵去探聽，不需要刻意依賴眼睛去窺視，不需要刻意依賴肌肉力量去強求，也不需要刻意依賴機謀心思去算計。企圖契合大道卻偏要用耳目視聽、形體力量與世俗聰明去強行求索，那就完全背道而馳了！看它看似就在眼前，忽然之間又變幻在身後；運用它時浩瀚充塞於宇宙六合虛空之中，收斂不用時卻杳然無蹤不知其所寄。這大道既非懷揣功利有心之人所能強行企及，亦非麻木無知無心之輩所能偶然接近。唯有在靜默無言中深刻領悟、並將其化為本然天性實踐的人才能真正獲得大道。洞曉一切真理卻不放縱私情偏見，具備一切才能卻不肆意妄為造作，這才是真正的大知大能啊！若一開始就毫無感知認知，又怎麼可能生發出純真情懷呢？若一開始就毫無實際能力，又怎麼可能做到超脫無為呢？聚集的泥土塊石也罷，堆積的塵土微塵也罷，世間雖然看似微賤無一物，卻無處不蘊含著大道的至高真理啊！\",\"analysis\":\"【篇旨與仲尼篇終結關尹子本體心法大成真知真能】〈仲尼〉終篇總結——關尹子以「在己無居、動水靜鏡應響、知而亡情、能而不為」作結，辨析真無為必須建立在「真知真能」基礎之上，萬物皆含大道之理。\\\\n【詞義訓詁】「發無知何能情，發不能何能為」：深刻批判愚昧無能者冒充道家「無知無為」，確立道家無為乃是大知大能之後的高度自我剋制與昇華；「聚塊積塵無非理」：一沙一世界，萬物皆具道體。\\\\n【哲理總結】徹底澄清了對道家「無為」的世俗誤解，確立了崇高博大的辯證認知論與知行合一境界。\",\"historicalContext\":\"\",\"keywords\":[]}}],\"sentences\":[{\"id\":\"liezi_ch-4_p-1_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-1\",\"order\":1,\"canonicalText\":\"仲尼閑居，子貢入侍，而有憂色。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-1_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-1\",\"order\":2,\"canonicalText\":\"子貢不敢問，出告顏回。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-1_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-1\",\"order\":3,\"canonicalText\":\"顏回援琴而歌。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-1_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-1\",\"order\":4,\"canonicalText\":\"孔子聞之，果召回入，問曰：「若奚獨樂？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-1_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-1\",\"order\":5,\"canonicalText\":\"」回曰：「夫子奚獨憂？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-1_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-1\",\"order\":6,\"canonicalText\":\"」孔子曰：「先言爾志。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-1_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-1\",\"order\":7,\"canonicalText\":\"」曰：「吾昔聞之夫子曰：『樂天知命故不憂。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-1_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-1\",\"order\":8,\"canonicalText\":\"』回所以樂也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-1_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-1\",\"order\":9,\"canonicalText\":\"」孔子愀然有間，曰：「有是言哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-1_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-1\",\"order\":10,\"canonicalText\":\"汝以夫子之言為盡然邪？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-1_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-1\",\"order\":11,\"canonicalText\":\"此吾昔日之小知也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-1_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-1\",\"order\":12,\"canonicalText\":\"曏者吾所言樂天知命，特未見其大者耳。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-1_s-13\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-1\",\"order\":13,\"canonicalText\":\"今吾憂者，憂天下之不治，億兆之不寧，道之不行，德之不章。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-1_s-14\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-1\",\"order\":14,\"canonicalText\":\"吾何能不憂哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-1_s-15\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-1\",\"order\":15,\"canonicalText\":\"樂天知命者，小人之自全也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-1_s-16\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-1\",\"order\":16,\"canonicalText\":\"憂世憫人者，聖人之宏願也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-1_s-17\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-1\",\"order\":17,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-2_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-2\",\"order\":1,\"canonicalText\":\"亢倉子居陳，人告亢倉子於陳侯，曰：「亢倉子得老聃之道，能以耳視而目聽。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-2_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-2\",\"order\":2,\"canonicalText\":\"」陳侯異之，使使厚幣聘之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-2_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-2\",\"order\":3,\"canonicalText\":\"亢倉子至，陳侯問其術。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-2_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-2\",\"order\":4,\"canonicalText\":\"亢倉子曰：「傳者妄也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-2_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-2\",\"order\":5,\"canonicalText\":\"臣能使耳目相通，不能使耳目代用。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-2_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-2\",\"order\":6,\"canonicalText\":\"」陳侯曰：「若此者，何道邪？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-2_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-2\",\"order\":7,\"canonicalText\":\"」亢倉子曰：「臣之體神凝形釋，骨肉都融。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-2_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-2\",\"order\":8,\"canonicalText\":\"臣不知形之所居，足之所履，心之所念，言之所藏。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-2_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-2\",\"order\":9,\"canonicalText\":\"眼如耳，耳如鼻，鼻如口，口無不同。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-2_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-2\",\"order\":10,\"canonicalText\":\"天下之物，至無不通，至無不察。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-2_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-2\",\"order\":11,\"canonicalText\":\"此臣之所謂耳目相通也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-2_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-2\",\"order\":12,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-3_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-3\",\"order\":1,\"canonicalText\":\"商丘開見老商氏，老商氏不言。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-3_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-3\",\"order\":2,\"canonicalText\":\"商丘開三年侍之，無所得。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-3_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-3\",\"order\":3,\"canonicalText\":\"乃往見伯高子，伯高子亦不言。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-3_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-3\",\"order\":4,\"canonicalText\":\"商丘開復侍之三年，亦無所得。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-3_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-3\",\"order\":5,\"canonicalText\":\"乃自省曰：「道在於己，不在於人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-3_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-3\",\"order\":6,\"canonicalText\":\"」退而居山，獨坐修養。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-3_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-3\",\"order\":7,\"canonicalText\":\"三年之後，大悟。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-3_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-3\",\"order\":8,\"canonicalText\":\"復見老商氏、伯高子，二子迎而笑曰：「子得之矣！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-3_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-3\",\"order\":9,\"canonicalText\":\"」故曰：至道無言，至德無跡。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-3_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-3\",\"order\":10,\"canonicalText\":\"求諸人者遠，求諸己者近。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-4_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-4\",\"order\":1,\"canonicalText\":\"子列子問於關尹曰：「至人之言，若響之應聲，若影之隨形。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-4_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-4\",\"order\":2,\"canonicalText\":\"何其神也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-4_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-4\",\"order\":3,\"canonicalText\":\"」關尹曰：「非神也，理自然也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-4_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-4\",\"order\":4,\"canonicalText\":\"夫響不求聲，而聲至則應；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-4_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-4\",\"order\":5,\"canonicalText\":\"影不求形，而形至則隨。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-4_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-4\",\"order\":6,\"canonicalText\":\"至人虛己以應物，不為物先，不為物後，故能無不應。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-4_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-4\",\"order\":7,\"canonicalText\":\"若有心於應，則有不應矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-4_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-4\",\"order\":8,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-5_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-5\",\"order\":1,\"canonicalText\":\"孔子窮於陳、蔡之間，七日不嘗粒，絃歌不絕。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-5_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-5\",\"order\":2,\"canonicalText\":\"子路入見曰：「夫子之道，蓋窮矣？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-5_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-5\",\"order\":3,\"canonicalText\":\"」孔子曰：「由！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-5_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-5\",\"order\":4,\"canonicalText\":\"夫芝蘭生於深林，不以無人而不芳；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-5_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-5\",\"order\":5,\"canonicalText\":\"君子修道立德，不以窮困而改節。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-5_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-5\",\"order\":6,\"canonicalText\":\"命也夫！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-5_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-5\",\"order\":7,\"canonicalText\":\"知其不可奈何而安之若命，此君子之所以為君子也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-5_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-5\",\"order\":8,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-6_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-6\",\"order\":1,\"canonicalText\":\"子列子學也，三年之後，心不敢念是非，口不敢言利害，始得老商一眄而已。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-6_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-6\",\"order\":2,\"canonicalText\":\"五年之後，心更念是非，口更言利害，老商始一解顏而笑。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-6_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-6\",\"order\":3,\"canonicalText\":\"七年之後，從心之所念，更無是非；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-6_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-6\",\"order\":4,\"canonicalText\":\"從口之所言，更無利害。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-6_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-6\",\"order\":5,\"canonicalText\":\"夫子始一引吾並席而坐。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-6_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-6\",\"order\":6,\"canonicalText\":\"九年之後，橫心之所念，橫口之所言，亦不知我之是非利害歟，亦不知彼之是非利害歟，外內進矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-6_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-6\",\"order\":7,\"canonicalText\":\"而後眼如耳，耳如鼻，鼻如口，口無不同。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-6_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-6\",\"order\":8,\"canonicalText\":\"心凝形釋骨肉都融；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-6_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-6\",\"order\":9,\"canonicalText\":\"不覺形之所倚，足之所履，心之所念，言之所藏。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-6_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-6\",\"order\":10,\"canonicalText\":\"如斯而已。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-6_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-6\",\"order\":11,\"canonicalText\":\"則理無所隱矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-7_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-7\",\"order\":1,\"canonicalText\":\"初子列子好遊。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-7_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-7\",\"order\":2,\"canonicalText\":\"壺丘子曰：「禦寇好遊，遊何所好？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-7_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-7\",\"order\":3,\"canonicalText\":\"」列子曰：「遊之樂，所玩無故。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-7_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-7\",\"order\":4,\"canonicalText\":\"人之遊也，觀其所見；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-7_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-7\",\"order\":5,\"canonicalText\":\"我之遊也，觀其所變。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-7_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-7\",\"order\":6,\"canonicalText\":\"遊乎遊乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-7_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-7\",\"order\":7,\"canonicalText\":\"未有能辨其遊者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-7_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-7\",\"order\":8,\"canonicalText\":\"」壺丘子曰：「禦寇之遊固與人同歟，而曰固與人異歟？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-7_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-7\",\"order\":9,\"canonicalText\":\"凡所見，亦恆見其變。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-7_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-7\",\"order\":10,\"canonicalText\":\"玩彼物之無故，不知我亦無故。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-7_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-7\",\"order\":11,\"canonicalText\":\"務外遊，不知務內觀。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-7_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-7\",\"order\":12,\"canonicalText\":\"外遊者，求備於物；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-7_s-13\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-7\",\"order\":13,\"canonicalText\":\"內觀者，取足於身。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-7_s-14\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-7\",\"order\":14,\"canonicalText\":\"取足於身，遊之至也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-7_s-15\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-7\",\"order\":15,\"canonicalText\":\"求備於物，遊之不至也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-7_s-16\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-7\",\"order\":16,\"canonicalText\":\"」於是列子終身不出，自以為不知遊。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-7_s-17\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-7\",\"order\":17,\"canonicalText\":\"壺丘子曰：「遊其至乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-7_s-18\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-7\",\"order\":18,\"canonicalText\":\"至遊者不知所適；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-7_s-19\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-7\",\"order\":19,\"canonicalText\":\"至觀者不知所眡，物物皆遊矣，物物皆觀矣，是我之所謂遊，是我之所謂觀也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-7_s-20\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-7\",\"order\":20,\"canonicalText\":\"故曰：遊其至矣乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-7_s-21\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-7\",\"order\":21,\"canonicalText\":\"遊其至矣乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-7_s-22\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-7\",\"order\":22,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-8_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-8\",\"order\":1,\"canonicalText\":\"龍叔謂文摯曰：「子之術微矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-8_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-8\",\"order\":2,\"canonicalText\":\"吾有疾，子能已乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-8_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-8\",\"order\":3,\"canonicalText\":\"」文摯曰：「唯命所聽。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-8_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-8\",\"order\":4,\"canonicalText\":\"然先言子所病之證。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-8_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-8\",\"order\":5,\"canonicalText\":\"」龍叔曰：「吾鄉譽不以為榮，國毀不以為辱；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-8_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-8\",\"order\":6,\"canonicalText\":\"得而不喜，失而弗憂；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-8_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-8\",\"order\":7,\"canonicalText\":\"視生如死，視富如貧，視人如豕，視吾如人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-8_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-8\",\"order\":8,\"canonicalText\":\"處吾之家，如逆旅之舍；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-8_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-8\",\"order\":9,\"canonicalText\":\"觀吾之鄉，如戎蠻之國。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-8_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-8\",\"order\":10,\"canonicalText\":\"凡此眾庶，爵賞不能勸，刑罰不能威，盛衰利害不能易，哀樂不能移。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-8_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-8\",\"order\":11,\"canonicalText\":\"固不可事國君，交親友，御妻子，制僕隸。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-8_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-8\",\"order\":12,\"canonicalText\":\"此奚疾哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-8_s-13\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-8\",\"order\":13,\"canonicalText\":\"奚方能已之乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-8_s-14\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-8\",\"order\":14,\"canonicalText\":\"」文摯乃命龍叔背明而立。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-8_s-15\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-8\",\"order\":15,\"canonicalText\":\"文摯自後嚮明而望之，既而曰：「嘻！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-8_s-16\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-8\",\"order\":16,\"canonicalText\":\"吾見子之心矣，方寸之地虛矣，幾聖人也！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-8_s-17\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-8\",\"order\":17,\"canonicalText\":\"子心六孔流通，一孔不達。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-8_s-18\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-8\",\"order\":18,\"canonicalText\":\"今以聖智為疾者，或由此乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-8_s-19\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-8\",\"order\":19,\"canonicalText\":\"非吾淺術所能已也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-8_s-20\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-8\",\"order\":20,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-9_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-9\",\"order\":1,\"canonicalText\":\"無所由而常生者，道也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-9_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-9\",\"order\":2,\"canonicalText\":\"由生而生，故雖終而不亡，常也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-9_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-9\",\"order\":3,\"canonicalText\":\"由生而亡，不幸也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-9_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-9\",\"order\":4,\"canonicalText\":\"有所由而常死者，亦道也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-9_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-9\",\"order\":5,\"canonicalText\":\"由死而死，故雖未終而自亡者，亦常；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-9_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-9\",\"order\":6,\"canonicalText\":\"由死而生，幸也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-9_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-9\",\"order\":7,\"canonicalText\":\"故無用而生謂之道，用道得終謂之常；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-9_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-9\",\"order\":8,\"canonicalText\":\"有所用而死者亦謂之道，用道而得死者亦謂之常。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-10_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-10\",\"order\":1,\"canonicalText\":\"季梁之死，楊朱望其門而歌；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-10_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-10\",\"order\":2,\"canonicalText\":\"隨梧之死，楊朱撫其屍而哭。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-10_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-10\",\"order\":3,\"canonicalText\":\"隸人之生，隸人之死，眾人且歌，眾人且哭。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-10_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-10\",\"order\":4,\"canonicalText\":\"人情之感，隨時而異，君子順自然之變，不以世俗之禮拘其心。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-11_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-11\",\"order\":1,\"canonicalText\":\"目將眇者先睹秋毫，耳將聾者先聞蚋飛，口將爽者先辨淄澠，鼻將窒者先覺焦朽，體將僵者先亟奔佚，心將迷者先識是非。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-11_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-11\",\"order\":2,\"canonicalText\":\"故物不至者則不反。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-12_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-12\",\"order\":1,\"canonicalText\":\"鄭之圃澤多賢，東裏多才。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-12_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-12\",\"order\":2,\"canonicalText\":\"圃澤之役有伯豐子者，行過東裏，遇鄧析。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-12_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-12\",\"order\":3,\"canonicalText\":\"鄧析顧其徒而笑曰：「為若舞彼來者奚若？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-12_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-12\",\"order\":4,\"canonicalText\":\"」其徒曰：「所願知也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-12_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-12\",\"order\":5,\"canonicalText\":\"」鄧析謂伯豐子曰：「汝知養養之義乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-12_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-12\",\"order\":6,\"canonicalText\":\"受人養而不能自養者，犬豕之類也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-12_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-12\",\"order\":7,\"canonicalText\":\"養物而物為我用者，人之力也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-12_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-12\",\"order\":8,\"canonicalText\":\"使汝之徒，食而飽，衣而息，執政之功也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-12_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-12\",\"order\":9,\"canonicalText\":\"長幼羣聚，而為牢藉庖廚之物，奚異犬豕之類乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-12_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-12\",\"order\":10,\"canonicalText\":\"」伯豐子不應。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-12_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-12\",\"order\":11,\"canonicalText\":\"伯豐子之從者越次而進曰：「大夫不聞齊魯之多機乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-12_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-12\",\"order\":12,\"canonicalText\":\"有善治土木者，有善治金革者，有善治聲樂者，有善治書數者，有善治軍旅者，有善治宗廟者，羣才備也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-12_s-13\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-12\",\"order\":13,\"canonicalText\":\"而無相位者，無能相使者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-12_s-14\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-12\",\"order\":14,\"canonicalText\":\"而位之者無知，使之者無能，而知之與能，為之使焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-12_s-15\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-12\",\"order\":15,\"canonicalText\":\"執政者迺吾之所使，子奚矜焉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-12_s-16\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-12\",\"order\":16,\"canonicalText\":\"」鄧析無以應，目其徒而退。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-13_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-13\",\"order\":1,\"canonicalText\":\"公儀伯以力聞諸侯，堂谿公言之於周宣王，王備禮以聘之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-13_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-13\",\"order\":2,\"canonicalText\":\"公儀伯至，觀形，懦夫也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-13_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-13\",\"order\":3,\"canonicalText\":\"宣王心惑而疑曰：「女之力何如？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-13_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-13\",\"order\":4,\"canonicalText\":\"」公儀伯曰：「臣之力能折春螽之股，堪秋蟬之翼。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-13_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-13\",\"order\":5,\"canonicalText\":\"」王作色曰：「吾之力者能裂犀兕之革，曳九牛之尾，猶憾其弱。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-13_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-13\",\"order\":6,\"canonicalText\":\"女折春螽之股，堪秋蟬之翼，而力聞天下，何也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-13_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-13\",\"order\":7,\"canonicalText\":\"」公儀伯長息退席曰：「善哉，王之問也！\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-13_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-13\",\"order\":8,\"canonicalText\":\"臣敢以實對。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-13_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-13\",\"order\":9,\"canonicalText\":\"臣之師有商丘子者，力無敵於天下，而六親不知，以未嘗用其力故也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-13_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-13\",\"order\":10,\"canonicalText\":\"臣以死事之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-13_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-13\",\"order\":11,\"canonicalText\":\"乃告臣曰：『人慾見其所不見，視人所不窺；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-13_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-13\",\"order\":12,\"canonicalText\":\"欲得其所不得，修人所不為。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-13_s-13\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-13\",\"order\":13,\"canonicalText\":\"故學眎者先見輿薪，學聽者先聞撞鍾。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-13_s-14\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-13\",\"order\":14,\"canonicalText\":\"夫有易於內者，無難於外。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-13_s-15\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-13\",\"order\":15,\"canonicalText\":\"於外無難，故名不出其一道。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-13_s-16\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-13\",\"order\":16,\"canonicalText\":\"』今臣之名聞於諸侯，是臣違師之教，顯臣之能者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-13_s-17\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-13\",\"order\":17,\"canonicalText\":\"然則臣之名不以負其力者也，以能用其力者也，不猶愈於負其力者乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-13_s-18\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-13\",\"order\":18,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":1,\"canonicalText\":\"中山公子牟者，魏國之賢公子也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":2,\"canonicalText\":\"好與賢人遊，不恤國事，而悅趙人公孫龍。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":3,\"canonicalText\":\"樂正子輿之徒笑之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":4,\"canonicalText\":\"公子牟曰：「子何笑牟之悅公孫龍也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":5,\"canonicalText\":\"」子輿曰：「公孫龍之為人也，行無師，學無友，佞給而不中，漫衍而無家，好怪而妄言。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":6,\"canonicalText\":\"欲惑人之心，屈人之口，與韓檀等肄之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":7,\"canonicalText\":\"」公子牟變容曰：「何子狀公孫龍之過歟？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":8,\"canonicalText\":\"請聞其實。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":9,\"canonicalText\":\"」子輿曰：「吾笑龍之詒孔穿，言『善射者，能令後鏃中前括，發發相及，矢矢相屬；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":10,\"canonicalText\":\"前矢造準，而無絕落，後矢之括猶銜弦，視之若一焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":11,\"canonicalText\":\"』孔穿駭之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":12,\"canonicalText\":\"龍曰：『此未其妙者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-13\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":13,\"canonicalText\":\"逢蒙之弟子曰鴻超，怒其妻而怖之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-14\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":14,\"canonicalText\":\"引烏號之弓，綦衛之箭，射其目。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-15\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":15,\"canonicalText\":\"矢來注眸子，而眶不睫，矢隧地而塵不揚。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-16\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":16,\"canonicalText\":\"』是豈智者之言與？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-17\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":17,\"canonicalText\":\"」公子牟曰：「智者之言，固非愚者之所曉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-18\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":18,\"canonicalText\":\"後鏃中前括，鈞後於前。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-19\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":19,\"canonicalText\":\"矢注眸子而眶不睫，盡矢之勢也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-20\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":20,\"canonicalText\":\"子何疑焉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-21\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":21,\"canonicalText\":\"」樂正子輿曰：「子龍之徒，焉得不飾其闕？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-22\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":22,\"canonicalText\":\"吾又言其尤者。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-23\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":23,\"canonicalText\":\"龍誑魏王曰：『有意不心。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-24\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":24,\"canonicalText\":\"有指不至。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-25\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":25,\"canonicalText\":\"有物不盡。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-26\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":26,\"canonicalText\":\"有影不移。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-27\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":27,\"canonicalText\":\"髮引千鈞。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-28\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":28,\"canonicalText\":\"白馬非馬。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-29\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":29,\"canonicalText\":\"孤犢未嘗有母。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-30\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":30,\"canonicalText\":\"』其負類反倫，不可勝言也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-31\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":31,\"canonicalText\":\"」公子牟曰：「子不諭至言而以為尤也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-32\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":32,\"canonicalText\":\"尤其在子矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-33\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":33,\"canonicalText\":\"夫無意則心同。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-34\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":34,\"canonicalText\":\"無指則皆至。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-35\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":35,\"canonicalText\":\"盡物者常有。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-36\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":36,\"canonicalText\":\"影不移者，說在改也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-37\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":37,\"canonicalText\":\"髮引千鈞，勢至等也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-38\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":38,\"canonicalText\":\"白馬非馬，形名離也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-39\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":39,\"canonicalText\":\"孤犢未嘗有母，非孤犢也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-40\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":40,\"canonicalText\":\"」樂正子輿曰：「子以公孫龍於馬皆條也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-41\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":41,\"canonicalText\":\"設令發於餘竅，子亦將承之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-42\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":42,\"canonicalText\":\"」公子牟默然良久告退曰：「請待餘日，更謁子論。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-14_s-43\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-14\",\"order\":43,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-15_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-15\",\"order\":1,\"canonicalText\":\"堯治天下五十年，不知天下治歟，不治歟？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-15_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-15\",\"order\":2,\"canonicalText\":\"不知億兆之願戴己歟，不願戴己歟？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-15_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-15\",\"order\":3,\"canonicalText\":\"顧問左右，左右不知；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-15_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-15\",\"order\":4,\"canonicalText\":\"問外朝，外朝不知；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-15_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-15\",\"order\":5,\"canonicalText\":\"問在野，在野不知。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-15_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-15\",\"order\":6,\"canonicalText\":\"堯乃微服遊於康衢，聞兒童謠曰：「立我蒸民，莫匪爾極。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-15_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-15\",\"order\":7,\"canonicalText\":\"不識不知，順帝之則。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-15_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-15\",\"order\":8,\"canonicalText\":\"」堯喜問曰：「誰教爾為此言？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-15_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-15\",\"order\":9,\"canonicalText\":\"」童兒曰：「我聞之大夫。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-15_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-15\",\"order\":10,\"canonicalText\":\"」問大夫，大夫曰：「古詩也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-15_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-15\",\"order\":11,\"canonicalText\":\"」堯還宮，召舜，因禪以天下。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-15_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-15\",\"order\":12,\"canonicalText\":\"舜不辭而受之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-16_s-1\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-16\",\"order\":1,\"canonicalText\":\"關尹喜曰：「在己無居，形物其著。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-16_s-2\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-16\",\"order\":2,\"canonicalText\":\"其動若水，其靜若鏡，其應若響。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-16_s-3\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-16\",\"order\":3,\"canonicalText\":\"故其道若物者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-16_s-4\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-16\",\"order\":4,\"canonicalText\":\"物自違道，道不違物。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-16_s-5\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-16\",\"order\":5,\"canonicalText\":\"善若道者，亦不用耳，亦不用目，亦不用力，亦不用心。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-16_s-6\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-16\",\"order\":6,\"canonicalText\":\"欲若道而用視聽形智以求之，弗當矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-16_s-7\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-16\",\"order\":7,\"canonicalText\":\"瞻之在前，忽焉在後；\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-16_s-8\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-16\",\"order\":8,\"canonicalText\":\"用之彌滿六虛，廢之莫知其所。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-16_s-9\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-16\",\"order\":9,\"canonicalText\":\"亦非有心者所能得遠，亦非無心者所能得近。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-16_s-10\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-16\",\"order\":10,\"canonicalText\":\"唯默而得之，而性成之者得之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-16_s-11\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-16\",\"order\":11,\"canonicalText\":\"知而亡情，能而不為，真知真能也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-16_s-12\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-16\",\"order\":12,\"canonicalText\":\"發無知，何能情？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-16_s-13\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-16\",\"order\":13,\"canonicalText\":\"發不能，何能為？\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-16_s-14\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-16\",\"order\":14,\"canonicalText\":\"聚塊也，積塵也，雖無一而非理也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"liezi_ch-4_p-16_s-15\",\"workId\":\"liezi\",\"chapterId\":\"liezi_ch-4\",\"passageId\":\"liezi_ch-4_p-16\",\"order\":15,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]}]}") as ChapterBundle
